    name: { de: "Gedenkstätte Theresienstadt", hu: "Terezín emlékhely", ro: "Memorialul Terezín", en: "Terezín Memorial"},
    image: "/poi-images/czechrepublic-terezin-memorial-history-v2.webp",
    coords: [14.1481, 50.5114],
